import Foundation
import SimulatorFrameTransportContracts

extension SimulatorFrameTransportActor {
    func handleSourceReconfiguring(_ message: SimulatorFrameStreamMessageReader) throws {
        // `.sourceReconfiguring` is accepted here too. The helper starts a second reconfiguration
        // whenever the source changes again before the first one applied - a device that is still
        // settling after a cold boot does exactly that - and it carries the unchanged generations,
        // so the identity guards below still prove it. Refusing it used to kill the whole run.
        guard phase == .streaming || phase == .updating || phase == .sourceReconfiguring else {
            throw SimulatorFrameTransportError.invalidMessage
        }
        try requireSessionIdentity(message)
        let token = try message.positive("requestToken")
        let _: SimulatorFrameStreamSourceReconfigureReason = try message.closedEnum(
            "reason", SimulatorFrameStreamSourceReconfigureReason.self
        )
        guard try message.positive("bootGeneration") == bootGeneration,
              try message.positive("screenID") == screenID,
              try message.string("screenUniqueID") == screenUniqueID,
              try message.positive("currentDisplayConfigurationGeneration")
              == displayConfigurationGeneration,
              try message.positive("currentConfigurationRevision") == configurationRevision,
              try message.positive("currentStreamGeneration") == streamGeneration,
              try message.unsigned("latestFrameSequence") == latestFrameSequence,
              try message.positive("sourceReleaseDeadlineContinuousNanoseconds") > 0
        else { throw SimulatorFrameTransportError.invalidMessage }
        resolvePendingUpdate(.superseded)
        sourceRequestToken = token
        phase = .sourceReconfiguring
        presentationMailbox?.setState(.updating, clearFrame: true)
        releaseCurrentIfNeeded(sendAcknowledgement: true)
        guard surfaceOwner.mappedSurfaceCount == 0, let deviceSet else {
            throw SimulatorFrameTransportError.invalidMessage
        }
        var builder = baseBuilder(.sourceReleaseReady, deviceSet: deviceSet)
        builder.put(token, "requestToken")
        builder.put(runID, "runID")
        builder.put(selectedSimulatorUDID, "selectedSimulatorUDID")
        builder.put(identityGeneration, "identityGeneration")
        builder.put(displayConfigurationGeneration, "currentDisplayConfigurationGeneration")
        builder.put(configurationRevision, "currentConfigurationRevision")
        builder.put(streamGeneration, "currentStreamGeneration")
        builder.put(lastReleasedFrameSequence, "releasedOldFrameSequence")
        builder.put(0, "mappedSurfaceCount")
        do {
            try session.send(builder.message())
        } catch {
            localTransportFailure()
        }
    }

    func handleSourceReconfigured(_ message: SimulatorFrameStreamMessageReader) throws {
        guard phase == .sourceReconfiguring, let token = sourceRequestToken else {
            throw SimulatorFrameTransportError.invalidMessage
        }
        try requireSessionIdentity(message)
        let nextDisplay = SimulatorFrameStreamScalarRule.nextMonotonic(
            displayConfigurationGeneration
        )
        let nextStream = SimulatorFrameStreamScalarRule.nextMonotonic(streamGeneration)
        let mode = try message.previewMode("appliedPreviewMode")
        let fps = try message.maximumFPS("appliedMaximumFPS")
        guard try message.positive("requestToken") == token,
              try message.positive("previousDisplayConfigurationGeneration")
              == displayConfigurationGeneration,
              try message.positive("appliedDisplayConfigurationGeneration") == nextDisplay,
              try message.positive("configurationRevision") == configurationRevision,
              try message.positive("previousStreamGeneration") == streamGeneration,
              try message.positive("appliedStreamGeneration") == nextStream,
              try message.positive("bootGeneration") > 0,
              try message.positive("screenID") <= UInt64(UInt32.max),
              try !(message.string("screenUniqueID")).isEmpty,
              try message.positive("nativePixelWidth") <= UInt64(UInt32.max),
              try message.positive("nativePixelHeight") <= UInt64(UInt32.max),
              try message.positive("outputPixelWidth") <= UInt64(UInt32.max),
              try message.positive("outputPixelHeight") <= UInt64(UInt32.max),
              try message.unsigned("pixelFormat") == SimulatorFrameStreamContract.bgraPixelFormat,
              try message.unsigned("activeRingSlotCount") == 3,
              try message.unsigned("stagingRingSlotCount") == 0,
              try message.unsigned("latestFrameSequence") == 0,
              mode == appliedPreviewMode,
              fps == appliedMaximumFPS
        else { throw SimulatorFrameTransportError.invalidMessage }
        bootGeneration = try message.positive("bootGeneration")
        screenID = try message.positive("screenID")
        screenUniqueID = try message.string("screenUniqueID")
        displayConfigurationGeneration = try message.positive(
            "appliedDisplayConfigurationGeneration"
        )
        streamGeneration = try message.positive("appliedStreamGeneration")
        outputPixelWidth = try message.positive("outputPixelWidth")
        outputPixelHeight = try message.positive("outputPixelHeight")
        latestFrameSequence = 0
        sourceRequestToken = nil
        phase = .streaming
        presentationMailbox?.setState(.starting, clearFrame: true)
    }

    func handleTerminating(_ message: SimulatorFrameStreamMessageReader) throws {
        guard !phase.isTerminal, phase != .terminating else {
            throw SimulatorFrameTransportError.invalidMessage
        }
        try requireCurrentIdentity(message)
        let correlation = try message.canonicalUUID("correlationUUID")
        let origin: SimulatorFrameStreamTerminalOrigin = try message.closedEnum(
            "origin", SimulatorFrameStreamTerminalOrigin.self
        )
        let helperFailure: SimulatorFrameStreamFailureReason?
        switch origin {
        case .failure:
            let reason: SimulatorFrameStreamFailureReason = try message.closedEnum(
                "reason", SimulatorFrameStreamFailureReason.self
            )
            helperFailure = reason
        case .requestedStop, .requestedCancel:
            let reason: SimulatorFrameStreamDisposition = try message.closedEnum(
                "reason", SimulatorFrameStreamDisposition.self
            )
            guard reason.rawValue == origin.rawValue else {
                throw SimulatorFrameTransportError.invalidMessage
            }
            helperFailure = nil
        }
        guard try message.unsigned("latestFrameSequence") == latestFrameSequence,
              try message.positive("terminalDeadlineContinuousNanoseconds") > 0,
              try message.unsigned("activeRingSlotCount") <= 3,
              try message.unsigned("stagingRingSlotCount") <= 3,
              try message.unsigned("activeRingSlotCount")
              + (message.unsigned("stagingRingSlotCount")) <= 6,
              let deviceSet
        else { throw SimulatorFrameTransportError.invalidMessage }
        if let helperFailure {
            recordTerminalCause(.helperFailure(.terminal(helperFailure)))
        }
        terminalCorrelationUUID = correlation
        resolvePendingUpdate(.superseded)
        sourceRequestToken = nil
        phase = .terminating
        presentationMailbox?.setState(.finalizing)
        releaseCurrentIfNeeded(sendAcknowledgement: true)
        guard surfaceOwner.mappedSurfaceCount == 0 else {
            throw SimulatorFrameTransportError.invalidMessage
        }
        var builder = baseBuilder(.terminalReleaseReady, deviceSet: deviceSet)
        builder.put(correlation, "correlationUUID")
        putCurrentIdentity(into: &builder)
        builder.put(lastReleasedFrameSequence, "releasedOldFrameSequence")
        builder.put(0, "mappedSurfaceCount")
        do {
            try session.send(builder.message())
        } catch {
            localTransportFailure()
        }
    }

    func handleFinal(_ message: SimulatorFrameStreamMessageReader) throws {
        guard phase == .terminating, let correlation = terminalCorrelationUUID else {
            throw SimulatorFrameTransportError.invalidMessage
        }
        try requireCurrentIdentity(message)
        guard try message.canonicalUUID("correlationUUID") == correlation,
              try message.unsigned("latestFrameSequence") == latestFrameSequence,
              try message.unsigned("activeRingSlotCount") == 0,
              try message.unsigned("stagingRingSlotCount") == 0
        else { throw SimulatorFrameTransportError.invalidMessage }
        _ = try message.unsigned("framesPublished")
        _ = try message.unsigned("framesDropped")
        _ = try message.unsigned("releasesAccepted")
        if message.kind == .streamStopped {
            let disposition: SimulatorFrameStreamDisposition = try message.closedEnum(
                "disposition", SimulatorFrameStreamDisposition.self
            )
            recordTerminalCause(disposition == .requestedStop ? .requestedStop : .requestedCancel)
            phase = .stopped
            presentationMailbox?.setState(.finalizing)
        } else {
            let reason: SimulatorFrameStreamFailureReason = try message.closedEnum(
                "reason", SimulatorFrameStreamFailureReason.self
            )
            terminalFailureReason = reason
            recordTerminalCause(.helperFailure(.terminal(reason)))
            phase = .failed
            presentationMailbox?.setState(.unavailable, clearFrame: true)
        }
        session.cancel(reason: "Simulator frame stream reached its final result.")
    }
}

