final class SimulatorFrameHelperService: @unchecked Sendable {
    private var listener: XPCListener?

    func run() throws {
        let hostEvidenceIsApproved = SimulatorFrameFrameworkProbe.hostEvidenceIsApproved()
        // Loading the three pinned frameworks is the one part of Gate 2 provenance no request can
        // influence. Acquiring the process-lifetime lease before the listener exists keeps the exact
        // pre/post-load fence and leaves the whole 10-second request deadline for real request work.
        let lease = SimulatorFrameFrameworkProbe.acquireGateTwoFrameworkLease(
            hostEvidenceIsApproved: hostEvidenceIsApproved
        )
        let runtime = SimulatorFrameHelperRuntime(
            hostEvidenceIsApproved: hostEvidenceIsApproved, gateTwoFrameworkLease: lease
        )
        let clientRequirement = XPCPeerRequirement.isFromSameTeam(
            andMatchesSigningIdentifier: SimulatorFrameTransportContract.mainAppBundleIdentifier
        )
        let listener: XPCListener = try XPCListener(
            service: SimulatorFrameTransportContract.helperBundleIdentifier,
            requirement: clientRequirement
        ) { request in
            let identitySession = SimulatorFrameHelperIdentitySession()
            let streamSessionBox = SimulatorFrameStreamSessionBox()
            let decision: XPCListener.IncomingSessionRequest.Decision
            let peerSession: XPCSession
            (decision, peerSession) = request.accept(
                incomingMessageHandler: { (message: XPCReceivedMessage) -> (any Encodable)? in
                    guard message.senderSatisfies(clientRequirement) else { return nil }
                    guard let discriminator = try? message.decode(as: SimulatorFrameHelperRequestDiscriminator.self) else {
                        return SimulatorFrameHelperRequestReplies.uncorrelatedIdentityRejection()
                    }
                    switch discriminator.kind {
                    case .ping:
                        guard let envelope = try? message.decode(as: SimulatorFrameHelperRequestEnvelope.self),
                              envelope.isExactlyOneMatchingPayload,
                              let ping = envelope.ping
                        else {
                            return SimulatorFrameHelperRequestReplies.rejectedPingResponse()
                        }
                        return runtime.handle(ping: ping)
                    case .stream:
                        // Gate 3 app-to-helper control is strict Codable on this same
                        // authenticated channel; every helper-to-app result is one XPCDictionary
                        // on the captured peer session.
                        guard let control = try? message.decode(
                            as: SimulatorFrameStreamControlMessage.self
                        ) else {
                            return nil
                        }
                        streamSessionBox.session()?.handle(control: control)
                        return nil
                    case .displayIdentity:
                        guard let correlation = try? message.decode(as: SimulatorFrameHelperIdentityCorrelationEnvelope.self),
                              SimulatorFrameHelperRuntime.isCanonicalUUID(correlation.header.requestUUID),
                              SimulatorFrameHelperRuntime.isCanonicalUUID(correlation.header.selectedSimulatorUDID)
                        else {
                            return SimulatorFrameHelperRequestReplies.uncorrelatedIdentityRejection()
                        }
                        guard let envelope = try? message.decode(as: SimulatorFrameHelperRequestEnvelope.self),
                              envelope.isExactlyOneMatchingPayload,
                              let identity = envelope.displayIdentity
                        else {
                            if let group = try? message.decode(as: SimulatorFrameHelperIdentityDeviceSetEnvelope.self) {
                                return SimulatorFrameHelperRequestReplies.correlatedGroupIdentityRejection(
                                    for: correlation.header,
                                    deviceSet: group.deviceSet
                                )
                            }
                            return SimulatorFrameHelperRequestReplies.correlatedNoGroupIdentityRejection(for: correlation.header)
                        }
                        runtime.handle(identity: identity, session: identitySession) { response in
                            message.reply(response)
                        }
                        return nil
                    }
                },
                cancellationHandler: { _ in
                    streamSessionBox.connectionInvalidated()
                    for (requestUUID, resources) in identitySession.cancelAll() {
                        SimulatorFrameIdentityProbeSignposts.emitTerminal(
                            requestUUID: requestUUID,
                            reason: .cancelled,
                            diagnostic: resources.diagnostic
                        )
                        resources.release(cancelAdapter: true)
                    }
                }
            )
            streamSessionBox.attach(peerSession)
            return decision
        }
        self.listener = listener
    }

}
