//
// File: SimulatorFrameTransportActorState.swift
// Created by Vision Capture MVP
//

import Dispatch
import Foundation
import SimulatorFrameTransportContracts

struct SimulatorFrameTransportPendingUpdate: Equatable {
    let requestUUID: String
    let currentRevision: UInt64
    let nextRevision: UInt64
    let currentStreamGeneration: UInt64
    let nextStreamGeneration: UInt64
    let displayConfigurationGeneration: UInt64
    let requestedPreviewMode: SimulatorFrameStreamPreviewMode
    let requestedMaximumFPS: SimulatorFrameStreamMaximumFPS
    let fitPixelWidth: UInt64
    let fitPixelHeight: UInt64
    let startedAtUptimeNanoseconds: UInt64
    var readyToSwitch = false
    var appliedAwaitingPostUpdateFrame = false
}

struct SimulatorFrameTransportPostUpdateFrameExpectation: Equatable {
    let requestUUID: String
    let startedAtUptimeNanoseconds: UInt64
    let configurationRevision: UInt64
    let streamGeneration: UInt64
    let displayConfigurationGeneration: UInt64
}

struct SimulatorFrameTransportAppliedConfiguration: Equatable {
    let previewMode: SimulatorFrameStreamPreviewMode
    let maximumFPS: SimulatorFrameStreamMaximumFPS
    let outputPixelWidth: UInt64
    let outputPixelHeight: UInt64
}

enum SimulatorFrameTransportConfigurationUpdateOutcome: Equatable {
    case applied(SimulatorFrameTransportAppliedConfiguration)
    case rejected
    case superseded
}

enum SimulatorFrameTransportUpdateAdmission {
    static func canBegin(
        phase: SimulatorFrameTransportPhase,
        hasPendingUpdate: Bool,
        hasPendingPostUpdateFrame: Bool
    ) -> Bool {
        phase == .streaming && !hasPendingUpdate && !hasPendingPostUpdateFrame
    }

    static func canPublishReady(mappedSurfaceCount: UInt64) -> Bool {
        mappedSurfaceCount == 0
    }
}

extension SimulatorFrameTransportActor {
    func resolvePendingUpdate(
        _ outcome: SimulatorFrameTransportConfigurationUpdateOutcome
    ) {
        if outcome == .superseded {
            if let pendingUpdate {
                SimulatorFrameTransportUpdateDiagnostics.superseded(
                    pendingUpdate,
                    now: DispatchTime.now().uptimeNanoseconds
                )
            }
            postUpdateFrameExpectation = nil
        }
        pendingUpdateContinuation?.resume(returning: outcome)
        pendingUpdateContinuation = nil
        pendingUpdate = nil
    }

    func baseBuilder(
        _ kind: SimulatorFrameStreamKind,
        deviceSet: SimulatorFrameStreamDeviceSetGroup
    ) -> SimulatorFrameStreamControlBuilder {
        SimulatorFrameStreamControlBuilder(kind: kind, deviceSet: deviceSet)
    }

    func putCurrentIdentity(into builder: inout SimulatorFrameStreamControlBuilder) {
        builder.put(runID, "runID")
        builder.put(selectedSimulatorUDID, "selectedSimulatorUDID")
        builder.put(identityGeneration, "identityGeneration")
        builder.put(displayConfigurationGeneration, "displayConfigurationGeneration")
        builder.put(configurationRevision, "configurationRevision")
        builder.put(streamGeneration, "streamGeneration")
    }

    func requireSessionIdentity(_ message: SimulatorFrameStreamMessageReader) throws {
        guard message.deviceSet == deviceSet,
              try message.canonicalUUID("runID") == runID,
              try message.canonicalUUID("selectedSimulatorUDID") == selectedSimulatorUDID,
              try message.positive("identityGeneration") == identityGeneration
        else { throw SimulatorFrameTransportError.invalidMessage }
    }

    func requireCurrentIdentity(_ message: SimulatorFrameStreamMessageReader) throws {
        try requireSessionIdentity(message)
        guard try message.positive("displayConfigurationGeneration")
            == displayConfigurationGeneration,
            try message.positive("configurationRevision") == configurationRevision,
            try message.positive("streamGeneration") == streamGeneration
        else { throw SimulatorFrameTransportError.invalidMessage }
    }

    /// Releases the frame the app is still holding.
    ///
    /// `stampWithCurrentIdentity` exists for the one caller that releases *after* an applied
    /// configuration change: the helper validates every `releaseFrame` against its own *current*
    /// configuration, and it advances that configuration before it announces the apply. A frame
    /// captured under the previous revision therefore has to be released naming the new one, or
    /// the helper ends the session. Every other caller releases while the two sides still agree,
    /// so the default keeps the frame's own captured identity exactly as before.
    func releaseCurrentIfNeeded(sendAcknowledgement: Bool, stampWithCurrentIdentity: Bool = false) {
        currentFrame = nil
        guard let released = surfaceOwner.releaseCurrent() else { return }
        lastReleasedFrameSequence = released.frameSequence
        if sendAcknowledgement {
            sendRelease(released, stampWithCurrentIdentity: stampWithCurrentIdentity)
        }
    }

    func sendRelease(_ released: SimulatorFrameCurrentFrame, stampWithCurrentIdentity: Bool = false) {
        guard let deviceSet else { return }
        var builder = baseBuilder(.releaseFrame, deviceSet: deviceSet)
        builder.put(runID, "runID")
        builder.put(selectedSimulatorUDID, "selectedSimulatorUDID")
        builder.put(identityGeneration, "identityGeneration")
        builder.put(stampWithCurrentIdentity
            ? displayConfigurationGeneration
            : released.displayConfigurationGeneration,
            "displayConfigurationGeneration")
        builder.put(stampWithCurrentIdentity ? configurationRevision : released.configurationRevision,
                    "configurationRevision")
        builder.put(stampWithCurrentIdentity ? streamGeneration : released.streamGeneration,
                    "streamGeneration")
        builder.put(released.frameSequence, "frameSequence")
        builder.put(released.slotID, "slotID")
        builder.put(released.leaseToken, "leaseToken")
        builder.put(released.surfaceID, "surfaceID")
        do {
            try session.send(builder.message())
            releasesSent &+= 1
        } catch {
            localTransportFailure()
        }
    }
