import Foundation
import XPC

/// Holds the accepted peer session so Gate 3 can push raw `XPCDictionary` frames on the same
/// authenticated connection, and creates the one stream session lazily on first control message.
///
/// A helper process that only ever serves Gate 1 ping or Gate 2 identity never creates a session,
/// so normal launch and the accepted Gate 2 route do exactly zero stream work.
final class SimulatorFrameStreamSessionBox: @unchecked Sendable {
    private let lock = NSLock()
    private var peer: XPCSession?
    private var stored: SimulatorFrameStreamSession?

    func attach(_ peerSession: XPCSession) {
        lock.lock()
        peer = peerSession
        lock.unlock()
    }

    func session() -> SimulatorFrameStreamSession? {
        lock.lock()
        defer { lock.unlock() }
        if let stored { return stored }
        guard let peer else { return nil }
        let created = SimulatorFrameStreamSession(peerSession: peer)
        stored = created
        return created
    }

    func connectionInvalidated() {
        lock.lock()
        let session = stored
        peer = nil
        stored = nil
        lock.unlock()
        session?.connectionInvalidated()
    }
}

