import Dispatch
import Foundation
import os
import SimulatorFrameManagedDeviceSet
import SimulatorFramePrivateAdapter
import SimulatorFrameTransportContracts
import XPC

/// The helper's own log. Until this existed, a `protocolViolation` terminal named no message and
/// no error, so the app could see only that the helper had refused *something*.
private let simulatorFrameStreamSessionLog = Logger(
    subsystem: SimulatorFrameTransportContract.helperBundleIdentifier,
    category: "streamSession"
)

/// The helper's closed Gate 3 stream session.
///
/// It serializes every wire fact on one utility-QoS session queue and is the sole owner of the
/// generations, the published frame sequence, the bounded lease pipeline, the heartbeat, and the
/// terminal handshake. App-to-helper control arrives as closed Codable through the existing
/// authenticated handler; helper-to-app messages are raw `XPCDictionary` on the accepted peer
/// session, because the `frame` envelope carries the public IOSurface XPC object.
final class SimulatorFrameStreamSession: @unchecked Sendable {
    let queue = DispatchQueue(
        label: "com.hebert.VisionCapture.frameStream.session", qos: .utility
    )
    let peerSession: XPCSession
    var phase: SimulatorFrameStreamSessionPhase = .idle
    var generations = SimulatorFrameStreamGenerations()
    var pipeline = SimulatorFrameStreamLeasePipeline()
    var counters = SimulatorFrameStreamSessionCounters()
    var stream: VCSimulatorFramePrivateStream?
    var sink: SimulatorFrameStreamSessionSink?
    /// Held for the whole stream when the request selects a managed device set, exactly as the
    /// accepted Gate 2 route requires. Released once at terminal cleanup.
    var managedLease: SimulatorFrameManagedDeviceSetLease?
    var heartbeatTimer: DispatchSourceTimer?

    var runID = ""
    var selectedSimulatorUDID = ""
    var deviceSet: SimulatorFrameStreamDeviceSetGroup?
    var appliedPreviewMode: SimulatorFrameStreamPreviewMode = .fitNotch
    var appliedMaximumFPS: SimulatorFrameStreamMaximumFPS = .thirty
    var outputPixelWidth: UInt64 = 0
    var outputPixelHeight: UInt64 = 0
    var bootGeneration: UInt64 = 0
    var screenID: UInt64 = 0
    var screenUniqueID = ""
    var resolvedBootGeneration: UInt64?
    var correlationUUID = ""
    var terminalOrigin: SimulatorFrameStreamTerminalOrigin?
    var terminalReason = ""
    var failureReason: SimulatorFrameStreamFailureReason?
    var terminalReleaseSatisfied = false
    var adapterTerminalCleanupFinished = false
    var xpcInvalidated = false
    var terminalDeadlineContinuousNanoseconds: UInt64 = 0
    var sourceReleaseDeadlineContinuousNanoseconds: UInt64 = 0
    var lastReleasedFrameSequence: UInt64 = 0
    var updateRequestToken: UInt64?
    var updateRequestUUID = ""
    var sourceRequestToken: UInt64?
    /// True once the app's `sourceReleaseReady` for the current `sourceRequestToken` was accepted.
    /// It disarms the release deadline: after this point the session is waiting on the adapter, not
    /// on the app, and the two must not share one timeout or one failure reason.
    var sourceReleaseAcknowledged = false
    var sourceReconfigureReason: SimulatorFrameStreamSourceReconfigureReason = .sourceSurfacesChanged
    var lastRequestToken: UInt64 = 0
    var pendingPreviewMode: SimulatorFrameStreamPreviewMode?
    var pendingMaximumFPS: SimulatorFrameStreamMaximumFPS?
    var pendingFitPixelWidth: UInt64?
    var pendingFitPixelHeight: UInt64?
    var pendingUpdateRejectionReason: SimulatorFrameStreamConfigurationRejectedReason?
    var pendingTerminalOrigin: SimulatorFrameStreamTerminalOrigin?
    var pendingTerminalReason: String?
    var pendingTerminalCorrelationUUID: String?
    var stagedFitPixelWidth: UInt64 = 0
    var stagedFitPixelHeight: UInt64 = 0
    var nativePixelWidth: UInt64 = 0
    var nativePixelHeight: UInt64 = 0

    init(peerSession: XPCSession) {
        self.peerSession = peerSession
    }

    /// The one app-to-helper control entry point. It never replies through the Codable channel:
    /// every helper-to-app result is one `XPCDictionary` on the peer session.
    func handle(control message: SimulatorFrameStreamControlMessage) {
        queue.async { [self] in
            do {
                try route(message)
            } catch {
                // The one place a routed control message can become `protocolViolation`. Naming
                // the kind, the phase, the configuration the helper is actually on, and the thrown
                // error is what makes this terminal cause attributable afterwards.
                simulatorFrameStreamSessionLog.error(
                    """
                    frameStreamSession event=protocolViolation \
                    kind=\(message.kind.rawValue, privacy: .public) \
                    phase=\(self.phase.rawValue, privacy: .public) \
                    configurationRevision=\(self.generations.configurationRevision, privacy: .public) \
                    streamGeneration=\(self.generations.streamGeneration, privacy: .public) \
                    error=\(String(describing: error), privacy: .public)
                    """
                )
                fail(.protocolViolation)
            }
        }
    }

    // MARK: - Adapter sink callbacks, already on the adapter state lane

    func adapterDidResolveIdentity(bootGeneration: UInt64) {
        queue.async { [self] in
            guard bootGeneration > 0 else { return }
            if phase == .starting {
                resolvedBootGeneration = bootGeneration
            } else if phase == .sourceReconfiguring {
                self.bootGeneration = bootGeneration
            }
        }
    }

    func adapterDidApplyInitialConfiguration(
        screenID: UInt32,
        screenUniqueID: String,
        outputWidth: Int,
        outputHeight: Int
    ) {
        queue.async { [self] in
            guard phase == .starting, let resolvedBootGeneration else {
                fail(.protocolViolation)
                return
            }
            self.screenID = UInt64(screenID)
            self.screenUniqueID = screenUniqueID
            self.bootGeneration = resolvedBootGeneration
            nativePixelWidth = UInt64(outputWidth)
            nativePixelHeight = UInt64(outputHeight)
            outputPixelWidth = appliedPreviewMode == .fitNotch
                ? stagedFitPixelWidth : nativePixelWidth
            outputPixelHeight = appliedPreviewMode == .fitNotch
                ? stagedFitPixelHeight : nativePixelHeight
            phase = .streaming
            sendStreamStarted()
            startHeartbeat()
        }
    }

    func adapterDidProduceLease(_ lease: SimulatorFrameStreamLeaseRecord) {
        queue.async { [self] in
            guard phase == .streaming else {
                stream?.releaseFrameLease(withSlotID: UInt8(lease.slotID), leaseToken: lease.leaseToken)
                return
            }
            counters.leasesReceived += 1
            switch pipeline.accept(lease, nextSequence: { generations.nextPublishedSequence() }) {
            case let .send(sendable):
                sendFrame(sendable)
            case .sequenceOverflow:
                fail(.monotonicValueOverflow)
            case let .coalesced(superseded):
                counters.framesDropped += 1
                if let superseded {
                    counters.unsentLeasesSuperseded += 1
                    stream?.releaseFrameLease(
                        withSlotID: UInt8(superseded.slotID), leaseToken: superseded.leaseToken
                    )
                }
            }
        }
    }

    func adapterDidFail(_ reason: SimulatorFrameStreamFailureReason) {
        queue.async { [self] in
            fail(reason)
        }
    }

    func adapterDidFinishTerminalCleanup() {
        queue.async { [self] in
            adapterTerminalCleanupFinished = true
            if phase == .failed, terminalOrigin == nil {
                stream = nil
                sink = nil
                managedLease?.release()
                managedLease = nil
                return
            }
            finishTerminalIfReady()
        }
    }

    // MARK: - Heartbeat

    func startHeartbeat() {
        let timer = DispatchSource.makeTimerSource(queue: queue)
        timer.schedule(
            deadline: .now() + .seconds(1),
            repeating: .nanoseconds(Int(SimulatorFrameStreamContract.heartbeatIntervalNanoseconds))
        )
        timer.setEventHandler { [weak self] in
            guard let self, phase == .streaming else { return }
            counters.heartbeats += 1
            sendHeartbeat()
        }
        heartbeatTimer = timer
        timer.resume()
    }

    func stopHeartbeat() {
        heartbeatTimer?.cancel()
        heartbeatTimer = nil
    }
}

/// One monotonic continuous reading for the helper-owned deadlines.
func VCFrameSessionContinuousNanoseconds() -> UInt64 {
    clock_gettime_nsec_np(CLOCK_MONOTONIC_RAW)
}

