import Foundation
import SimulatorFramePrivateAdapter
import SimulatorFrameTransportContracts

extension SimulatorFrameStreamSession {
    func releaseFrame(_ message: SimulatorFrameStreamControlMessage) throws {
        guard phase == .streaming || phase == .updating || phase == .sourceReconfiguring
            || phase == .terminating
        else { throw SimulatorFrameStreamWireError.unexpectedKeySet }
        try requireCurrentConfigurationIdentity(message)
        let slotID = try message.unsigned("slotID")
        let leaseToken = try message.positive("leaseToken")
        let frameSequence = try message.positive("frameSequence")
        let surfaceID = try message.positive("surfaceID")
        guard SimulatorFrameStreamScalarRule.isValidSlotID(slotID),
              SimulatorFrameStreamScalarRule.isValidSurfaceID(surfaceID),
              let current = pipeline.current,
              current.slotID == slotID,
              current.leaseToken == leaseToken,
              current.frameSequence == frameSequence,
              current.surfaceID == surfaceID
        else { throw SimulatorFrameStreamWireError.outOfRange("slotID") }
        switch pipeline.release(
            slotID: slotID, leaseToken: leaseToken,
            nextSequence: { generations.nextPublishedSequence() }
        ) {
        case .rejected:
            counters.invalidReleases += 1
            fail(.acknowledgementInvalid)
        case let .sequenceOverflow(freed):
            releaseToAdapter(freed)
            fail(.monotonicValueOverflow)
        case let .accepted(freed, sendNext):
            counters.releasesAccepted += 1
            lastReleasedFrameSequence = freed.frameSequence
            releaseToAdapter(freed)
            if let next = sendNext { sendFrame(next) }
        }
    }

    func acknowledge(_ message: SimulatorFrameStreamControlMessage) throws {
        guard phase == .terminating else { throw SimulatorFrameStreamWireError.unexpectedKeySet }
        try requireCurrentConfigurationIdentity(message)
        guard try message.canonicalUUID("correlationUUID") == correlationUUID,
              try message.unsigned("releasedOldFrameSequence") == lastReleasedFrameSequence,
              try message.unsigned("mappedSurfaceCount") == 0,
              pipeline.isFullyReleased
        else {
            upgradeTerminalFailure(.terminalReleaseInvalid)
            releaseAllPipelineLeases()
            terminalReleaseSatisfied = true
            finishTerminalIfReady()
            return
        }
        terminalReleaseSatisfied = true
        finishTerminalIfReady()
    }

    func stop(_ message: SimulatorFrameStreamControlMessage) throws {
        try requireCurrentConfigurationIdentity(message)
        let disposition = try message.closedEnum("disposition", SimulatorFrameStreamDisposition.self)
        let requestUUID = try message.canonicalUUID("requestUUID")
        let origin: SimulatorFrameStreamTerminalOrigin = disposition == .requestedStop
            ? .requestedStop : .requestedCancel
        if let token = updateRequestToken {
            pendingTerminalOrigin = origin
            pendingTerminalReason = disposition.rawValue
            pendingTerminalCorrelationUUID = requestUUID
            pendingUpdateRejectionReason = disposition == .requestedStop
                ? .supersededByStop : .supersededByCancel
            stream?.discardStagedConfiguration(withRequestToken: token)
            return
        }
        correlationUUID = requestUUID
        beginTerminal(origin: origin, reason: disposition.rawValue)
    }

    func makeAdapterConfiguration(
        mode: SimulatorFrameStreamPreviewMode,
        fps: SimulatorFrameStreamMaximumFPS,
        width: UInt64,
        height: UInt64
    ) -> VCSimulatorFramePrivateConfiguration {
        VCSimulatorFramePrivateConfiguration(
            previewMode: mode == .fitNotch ? .fitNotch : .nativeDevice,
            maximumFPS: UInt(fps.rawValue), fitPixelWidth: Int(width), fitPixelHeight: Int(height)
        )
    }

    func requireStreamIdentity(_ message: SimulatorFrameStreamControlMessage) throws {
        try requireSessionIdentity(message)
        guard try message.positive("streamGeneration") == generations.streamGeneration
        else { throw SimulatorFrameStreamWireError.outOfRange("streamGeneration") }
    }

    func requireSessionIdentity(_ message: SimulatorFrameStreamControlMessage) throws {
        guard try message.canonicalUUID("runID") == runID,
              try message.canonicalUUID("selectedSimulatorUDID") == selectedSimulatorUDID,
              try message.positive("identityGeneration") == generations.identityGeneration,
              message.deviceSet == deviceSet
        else { throw SimulatorFrameStreamWireError.outOfRange("identityGeneration") }
    }

    func requireCurrentConfigurationIdentity(_ message: SimulatorFrameStreamControlMessage) throws {
        try requireStreamIdentity(message)
        guard try message.positive("displayConfigurationGeneration")
            == generations.displayConfigurationGeneration,
            try message.positive("configurationRevision") == generations.configurationRevision
        else { throw SimulatorFrameStreamWireError.outOfRange("configurationRevision") }
    }

    func fail(_ reason: SimulatorFrameStreamFailureReason) {
        guard phase != .stopped, phase != .failed, terminalOrigin != .failure else { return }
        if phase == .starting || phase == .idle {
            sendRejected(reason: Self.rejectedReason(for: reason))
            phase = .failed
            return
        }
        failureReason = reason
        if phase != .terminating { correlationUUID = UUID().uuidString.lowercased() }
        beginTerminal(origin: .failure, reason: reason.rawValue)
    }

    static func rejectedReason(
        for reason: SimulatorFrameStreamFailureReason
    ) -> SimulatorFrameStreamRejectedReason {
        switch reason {
        case .unsupportedCompatibilityOrABI: .unsupportedCompatibilityOrABI
        case .invalidConfiguration: .invalidConfiguration
        case .deviceIdentityChanged: .deviceUnavailable
        case .displayIdentityChanged: .displayUnavailable
        case .callbackRegistrationFailed: .callbackRegistrationFailed
        case .destinationAllocationFailed: .destinationAllocationFailed
        case .monotonicValueOverflow: .monotonicValueOverflow
        case .cancelled: .cancelled
        default: .invalidRequest
        }
    }

    func releaseToAdapter(_ lease: SimulatorFrameStreamLeaseRecord) {
        stream?.releaseFrameLease(withSlotID: UInt8(lease.slotID), leaseToken: lease.leaseToken)
    }

    func beginTerminal(origin: SimulatorFrameStreamTerminalOrigin, reason: String) {
        if let existing = terminalOrigin {
            let rank: (SimulatorFrameStreamTerminalOrigin) -> Int = {
                switch $0 {
                case .failure: 3
                case .requestedCancel: 2
                case .requestedStop: 1
                }
            }
            guard rank(origin) > rank(existing) else { return }
        }
        terminalOrigin = origin
        terminalReason = reason
        guard phase != .terminating else { return }
        phase = .terminating
        stopHeartbeat()
        stream?.stop()
        if let unsent = pipeline.releaseNewestUnsent() { releaseToAdapter(unsent) }
        let now = VCFrameSessionContinuousNanoseconds()
        guard let absolute = SimulatorFrameStreamScalarRule.nextAdding(
            now, SimulatorFrameStreamContract.releaseDeadlineNanoseconds
        ) else {
            upgradeTerminalFailure(.monotonicValueOverflow)
            terminalReleaseSatisfied = true
            releaseAllPipelineLeases()
            finishTerminalIfReady()
            return
        }
        terminalDeadlineContinuousNanoseconds = absolute
        sendTerminating(origin: origin, reason: reason)
        queue.asyncAfter(
            deadline: .now()
                + .nanoseconds(Int(SimulatorFrameStreamContract.releaseDeadlineNanoseconds))
        ) { [self] in
            guard phase == .terminating else { return }
            upgradeTerminalFailure(.terminalReleaseTimedOut)
            releaseAllPipelineLeases()
            terminalReleaseSatisfied = true
            finishTerminalIfReady()
        }
    }

    func releaseAllPipelineLeases() {
        for lease in pipeline.drainAll() {
            releaseToAdapter(lease)
        }
    }

    func upgradeTerminalFailure(_ reason: SimulatorFrameStreamFailureReason) {
        failureReason = reason
        terminalOrigin = .failure
        terminalReason = reason.rawValue
    }

    func finishTerminalIfReady() {
        guard phase == .terminating, terminalReleaseSatisfied,
              adapterTerminalCleanupFinished, pipeline.isFullyReleased
        else { return }
        phase = terminalOrigin == .failure ? .failed : .stopped
        if !xpcInvalidated { sendFinal() }
        stream = nil
        sink = nil
        managedLease?.release()
        managedLease = nil
    }

    func connectionInvalidated() {
        queue.async { [self] in
            guard !phase.isTerminalOrBeyond || phase == .terminating else { return }
            xpcInvalidated = true
            if phase != .terminating {
                correlationUUID = UUID().uuidString.lowercased()
                terminalOrigin = .failure
                failureReason = .xpcSendFailed
                phase = .terminating
                stopHeartbeat()
                stream?.stop()
            }
            releaseAllPipelineLeases()
            terminalReleaseSatisfied = true
            finishTerminalIfReady()
        }
    }
}

              descriptor:(id)descriptor
           sourceContext:(VCIdentityResolutionContext *)sourceContext {
    VCFrameLogCompleteIdentityEntry(
        (unsigned long)reason, identity != nil, descriptor != nil, self.terminal
    );
    if (self.terminal) {
