    }
    self.identityOperation = nil;
    if (identity == nil || reason != VCSimulatorFramePrivateIdentityReasonNone) {
        [self failOnStateQueueWithReason:VCFrameStreamFailureForIdentityReason(reason)];
        return;
    }
    if (descriptor == nil || sourceContext == nil) {
        [self failOnStateQueueWithReason:VCSimulatorFramePrivateStreamFailureDisplayIdentityChanged];
        return;
    }
