    // stream registers anything or reads one framebuffer surface.
    if (!VCFrameValidateStreamDescriptorABI(descriptor)) {
        [self failOnStateQueueWithReason:VCSimulatorFramePrivateStreamFailureUnsupportedCompatibilityOrABI];
        return;
    }
    size_t nativeWidth = 0;
    size_t nativeHeight = 0;
    if (!VCFrameConvertNativeDimension(identity.pixelWidth, &nativeWidth) ||
        !VCFrameConvertNativeDimension(identity.pixelHeight, &nativeHeight)) {
        [self failOnStateQueueWithReason:VCSimulatorFramePrivateStreamFailureInvalidConfiguration];
        return;
    }
    self.privateSourceContext = sourceContext;
    self.displayDescriptor = descriptor;
    VCFrameLogSourceGraphAcquired();
    self.identity = identity;
    self.nativePixelWidth = nativeWidth;
    self.nativePixelHeight = nativeHeight;
    if (![self advanceSourceConfigurationTokenOnStateQueue]) {
        return;
    }
    self.displayConfiguration = [[VCSimulatorFramePrivateDisplayConfiguration alloc]
        initWithSourceConfigurationToken:self.sourceConfigurationToken
                                screenID:identity.screenID
                          screenUniqueID:identity.screenUniqueID
                        nativePixelWidth:nativeWidth
                       nativePixelHeight:nativeHeight];
    if (![self installActiveRingOnStateQueueForConfiguration:self.configuration]) {
        return;
    }
    if (![self registerCallbacksOnStateQueue]) {
        return;
    }
    [self.sink privateStream:self didResolveIdentity:identity];
    [self.sink privateStream:self didApplyInitialDisplayConfiguration:self.displayConfiguration];
}
- (BOOL)installActiveRingOnStateQueueForConfiguration:(VCSimulatorFramePrivateConfiguration *)configuration {
    size_t width = configuration.previewMode == VCSimulatorFramePrivatePreviewModeFitNotch
        ? configuration.fitPixelWidth
        : self.nativePixelWidth;
    size_t height = configuration.previewMode == VCSimulatorFramePrivatePreviewModeFitNotch
        ? configuration.fitPixelHeight
        : self.nativePixelHeight;
    BOOL scratchAllocated = YES;
    VCFrameRing *ring = [VCFrameRing ringWithPreviewMode:configuration.previewMode
                                              pixelWidth:width
                                             pixelHeight:height
                                        sourcePixelWidth:self.nativePixelWidth
                                       sourcePixelHeight:self.nativePixelHeight
                                        scratchAllocated:&scratchAllocated];
    if (ring == nil) {
        [self failOnStateQueueWithReason:VCSimulatorFramePrivateStreamFailureDestinationAllocationFailed];
        return NO;
    }
    self.activeRing = ring;
    return YES;
}
- (BOOL)registerCallbacksOnStateQueue {
    VCFrameSourceCallbackBaseline *baseline =
        VCFrameBuildSourceCallbackBaseline(self.displayDescriptor, self.identity);
    if (baseline == nil) {
        [self failOnStateQueueWithReason:VCSimulatorFramePrivateStreamFailureRawSurfaceInvalid];
        return NO;
    }
    NSUUID *callbackUUID = [NSUUID UUID];
    uint64_t generationToken = self.sourceConfigurationToken;
    self.sourceCallbackBaseline = baseline;
    self.awaitingInitialSurfacesSnapshot = YES;
    self.awaitingInitialPropertiesSnapshot = YES;
    self.sourceReconfigurationAnnounced = NO;
    __weak VCSimulatorFramePrivateStream *weakSelf = self;
    id<VCSimScreenStreamCalling> screen = self.displayDescriptor;
