static BOOL VCFrameLayoutsEqual(VCFrameSurfaceLayout left, VCFrameSurfaceLayout right) {
    return left.width == right.width &&
        left.height == right.height &&
        left.bytesPerRow == right.bytesPerRow &&
        left.planeCount == right.planeCount &&
        left.bytesPerElement == right.bytesPerElement &&
        left.pixelFormat == right.pixelFormat;
}

VCFrameSourceCallbackBaseline *VCFrameBuildSourceCallbackBaseline(
    id descriptor,
    VCSimulatorFramePrivateDisplayIdentity *identity
) {
    if (descriptor == nil || identity == nil) {
        return nil;
    }
    VCDisplayMetadata *metadata = VCMetadataForDisplayDescriptor(descriptor);
    if (metadata == nil || metadata.screenID != identity.screenID ||
        ![metadata.uniqueID isEqualToString:identity.screenUniqueID] ||
        metadata.rawScreenType != identity.rawScreenType ||
        metadata.rawDisplayClass != identity.rawDisplayClass ||
        metadata.pixelSize.width != identity.pixelWidth ||
        metadata.pixelSize.height != identity.pixelHeight) {
        return nil;
    }
    id surfaceObject = [(id<VCSimDisplayIOSurfaceRenderableCalling>)descriptor framebufferSurface];
    if (surfaceObject == nil || CFGetTypeID((__bridge CFTypeRef)surfaceObject) != IOSurfaceGetTypeID()) {
        return nil;
    }
    IOSurfaceRef surface = (IOSurfaceRef)(__bridge CFTypeRef)surfaceObject;
    VCFrameSurfaceLayout layout;
    size_t acceptedWidth = 0;
    size_t acceptedHeight = 0;
    uint32_t surfaceID = IOSurfaceGetID(surface);
    if (!VCFrameConvertNativeDimension(identity.pixelWidth, &acceptedWidth) ||
        !VCFrameConvertNativeDimension(identity.pixelHeight, &acceptedHeight) ||
        surfaceID == 0 || !VCFrameReadSurfaceLayout(surface, &layout) ||
        layout.width != acceptedWidth || layout.height != acceptedHeight) {
        return nil;
    }
    return [[VCFrameSourceCallbackBaseline alloc] initWithSurfaceID:surfaceID
                                                            layout:layout
                                                          metadata:metadata];
}

BOOL VCFrameSurfaceMatchesBaseline(id surfaceObject, VCFrameSourceCallbackBaseline *baseline) {
    if (surfaceObject == nil || baseline == nil ||
        CFGetTypeID((__bridge CFTypeRef)surfaceObject) != IOSurfaceGetTypeID()) {
        return NO;
    }
    IOSurfaceRef surface = (IOSurfaceRef)(__bridge CFTypeRef)surfaceObject;
    VCFrameSurfaceLayout layout;
    return IOSurfaceGetID(surface) == baseline.surfaceID &&
        VCFrameReadSurfaceLayout(surface, &layout) && VCFrameLayoutsEqual(layout, baseline.surfaceLayout);
}

BOOL VCFrameSurfaceCallbackMatchesBaseline(
    id unmaskedSurface,
    id descriptor,
    VCFrameSourceCallbackBaseline *baseline
) {
    id currentObject = [(id<VCSimDisplayIOSurfaceRenderableCalling>)descriptor framebufferSurface];
    return VCFrameSurfaceMatchesBaseline(unmaskedSurface, baseline) &&
        VCFrameSurfaceMatchesBaseline(currentObject, baseline);
}

BOOL VCFramePropertiesCallbackMatchesBaseline(
    id properties,
    id descriptor,
    VCFrameSourceCallbackBaseline *baseline
) {
    if (properties == nil || baseline == nil ||
        !VCValidateProxySafeProtocolMethod(
            properties, @"SimScreenProperties", @selector(screenID), "I16@0:8"
        ) ||
        !VCValidateProxySafeProtocolMethod(
