- (void)handleSurfacesChangedForToken:(uint64_t)generationToken unmaskedSurface:(id)unmasked {
    if (self.terminal || self.sourceReconfigurationAnnounced ||
        generationToken != self.sourceConfigurationToken) {
        return;
    }
    if (self.awaitingInitialSurfacesSnapshot) {
        self.awaitingInitialSurfacesSnapshot = NO;
        self.firstSurfacesSnapshotSeen = YES;
        if (VCFrameSurfaceCallbackMatchesBaseline(
                unmasked, self.displayDescriptor, self.sourceCallbackBaseline
            )) {
            [self admitInitialSurfaceSnapshotForToken:generationToken];
            return;
        }
    }
    [self handleSourceChangeForToken:generationToken reason:VCFrameSourceChangeSurfaces];
}

- (void)handlePropertiesChangedForToken:(uint64_t)generationToken properties:(id)properties {
    if (self.terminal || self.sourceReconfigurationAnnounced ||
        generationToken != self.sourceConfigurationToken) {
        return;
    }
    if (self.awaitingInitialPropertiesSnapshot) {
        self.awaitingInitialPropertiesSnapshot = NO;
        self.firstPropertiesSnapshotSeen = YES;
        if (VCFramePropertiesCallbackMatchesBaseline(
                properties, self.displayDescriptor, self.sourceCallbackBaseline
            )) {
            return;
        }
    }
    [self handleSourceChangeForToken:generationToken reason:VCFrameSourceChangeProperties];
}

- (void)handleSourceChangeForToken:(uint64_t)generationToken reason:(VCFrameSourceChangeReason)reason {
    if (self.terminal || self.sourceReconfigurationAnnounced ||
        generationToken != self.sourceConfigurationToken) {
        return;
    }
    self.sourceReconfigurationAnnounced = YES;
    VCFrameLogSourceChange((unsigned long)reason);
    // A source change outranks a setting update, including while admission is already fenced.
    if (self.hasStagedTransaction) {
        [self discardStagingOnStateQueue];
        self.stagingRejections += 1;
    }
    self.admissionFenced = YES;
    if (self.pendingRawCandidate != NULL) {
        CFRelease(self.pendingRawCandidate);
        self.pendingRawCandidate = NULL;
    }
    uint64_t requestToken = self.sourceConfigurationToken;
    VCSimulatorFramePrivateSourceReconfigurationReason wireReason =
        reason == VCFrameSourceChangeProperties
            ? VCSimulatorFramePrivateSourceReconfigurationReasonPropertiesChanged
            : VCSimulatorFramePrivateSourceReconfigurationReasonSurfacesChanged;
    [self.sink privateStream:self
        didBeginAutomaticSourceReconfigurationFrom:self.displayConfiguration
                                             reason:wireReason
                                     requestToken:requestToken];
}

